contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller, address seedCaller) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        require(caller != address(0), "caller must not be zero");

        // Seed the market as a known caller (the test contract) so the call path is live.
        c.seedMarket{value: 0}(0); if (__ESBMC_reverted()) return;

        address ceoBefore = c.ceoAddress(); if (__ESBMC_reverted()) return;
        require(ceoBefore != caller, "caller must not already be CEO");

        bool reverted;
        c.DrugDealer(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && c.ceoAddress() == ceoBefore);
    }

    receive() external payable {}
}

