pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(address caller, address seedCaller) internal {
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(caller != address(0));
        try c.seedMarket{value: 0}(0) {} catch { return; }
        address ceoBefore;
        try c.ceoAddress() returns (address __r) { ceoBefore = __r; } catch { return; }
        vm.assume(ceoBefore != caller);
        bool reverted;
        try c.DrugDealer() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.ceoAddress() == ceoBefore);
    }

    function testFuzz_run(address caller, address seedCaller) public {
        vm.assume(caller.code.length == 0 && uint160(caller) > 0xffff && caller != address(this) && caller != address(c) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(seedCaller.code.length == 0 && uint160(seedCaller) > 0xffff && seedCaller != address(this) && seedCaller != address(c) && seedCaller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && seedCaller != 0x000000000000000000636F6e736F6c652e6c6f67 && seedCaller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && seedCaller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(caller, seedCaller);
    }

    receive() external payable {}
}
